 $channels='[{"name":"Das Erste","url":"https://daserste-live.ard-mcdn.de/daserste/live/hls/int/master.m3u8","available":true,"quality":"1080p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Das_Erste_2014.svg/500px-Das_Erste_2014.svg.png"},{"name":"ZDF","url":"https://zdf-hls-15.akamaized.net/hls/live/2016498/de/high/master.m3u8","available":true,"quality":"720p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/ZDF_logo.svg/500px-ZDF_logo.svg.png"},{"name":"3sat","url":"https://zdf-hls-18.akamaized.net/hls/live/2016501/dach/high/master.m3u8","available":true,"quality":"720p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/3sat_2019.svg/500px-3sat_2019.svg.png"},{"name":"arte","url":"https://artesimulcast.akamaized.net/hls/live/2030993/artelive_de/index.m3u8","available":true,"quality":"720p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Arte_Logo_2017.svg/250px-Arte_Logo_2017.svg.png"},{"name":"ZDFneo","url":"https://zdf-hls-16.akamaized.net/hls/live/2016499/de/high/master.m3u8","available":true,"quality":"720p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/8/8c/ZDFneo2017_Logo.svg/500px-ZDFneo2017_Logo.svg.png"},{"name":"ZDFinfo","url":"https://zdf-hls-17.akamaized.net/hls/live/2016500/de/high/master.m3u8","available":true,"quality":"720p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/3/34/ZDFinfo_2011.svg/500px-ZDFinfo_2011.svg.png"},{"name":"phoenix","url":"https://zdf-hls-19.akamaized.net/hls/live/2016502/de/high/master.m3u8","available":true,"quality":"720p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Phoenix-logo-2018.svg/500px-Phoenix-logo-2018.svg.png"},{"name":"KiKA","url":"https://kikageohls.akamaized.net/hls/live/2022693/livetvkika_de/master.m3u8","available":true,"quality":"1080p","logo":"https://upload.wikimedia.org/wikipedia/commons/thumb/f/f5/Kika_2012.svg/500px-Kika_2012.svg.png"},{"name":"SWR Rheinland-Pfalz","url":"https://