 $html='<section id="odpc-tv" data-channels="'.esc_attr($channels).'"><video id="odpc-tv-video" controls playsinline preload="none"></video><p id="odpc-tv-status" role="status">Verfügbare Sender werden geprüft …</p><div id="odpc-tv-grid" aria-label="Geprüfte Sender"></div></section>';
 $html.='<style>#odpc-tv{max-width:1040px;margin:auto}#odpc-tv-video{display:block;width:100%;aspect-ratio:16/9;background:#080d18;border-radius:12px}#odpc-tv-status{font-size:13px;color:#68788c;margin:10px 0 16px}#odpc-tv-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(130px,1fr));gap:10px}#odpc-tv-grid button{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:7px;min-height:86px;border:1px solid #d7e1ed;border-radius:12px;background:#fff;color:#15263b;cursor:pointer;padding:10px;font:inherit;font-size:13px}#odpc-tv-grid button:hover,#odpc-tv-grid button:focus-visible{border-color:#2275b6;background:#f1f8ff}#odpc-tv-grid img{height:35px;max-width:95px;object-fit:contain}#odpc-tv-grid .odpc-tv-wordmark{display:block;font-size:19px;font-weight:800;line-height:1.1;letter-spacing:-.5px;text-align:center;overflow-wrap:anywhere;color:#123a62}#odpc-tv-grid [hidden]{display:none!important}@media(max-width:480px){#odpc-tv-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}</style>';
 $html.='<script src="https://cdn.jsdelivr.net/npm/hls.js@1.5.20/dist/hls.min.js"></script>';
 $html.='<script>(function(){const root=document.getElementById("odpc-tv");if(!root)return;const channels=JSON.parse(root.dataset.channels||"[]"),video=root.querySelector("video"),grid=root.querySelector("#odpc-tv-grid"),status=root.querySelector("#odpc-tv-status");let player=null;function cleanup(){if(player){player.destroy();player=null}video.pause();video.removeAttribute("src");video.load()}function attach(c,v,ready,fail){let h=null;if(window.Hls&&Hls.isSupported()){h=new Hls({maxBufferLength:12});h.on(Hls.Events.ERROR,(_,e)=>{if(e.fatal)fail()});h.loadSource(c.url);h.attachMedia(v)}else if(v.canPlayType("application/vnd.apple.mpegurl")){v.src=c.url}else{fail()}return h}function play(c){cleanup();status.textContent="Verbinde: "+c.name;player=attach(c,video,()=>{},()=>{status.textContent=c.name+" aktuell nicht abspielbar";grid.querySelectorAll("button").forEach(b=>{if(b.dataset.name===c.name)b.remove()})});video.play().then(()=>{status.textContent=c.name}).catch(()=>{status.textContent="Zum Starten Play drücken"})}function show(c){if(grid.querySelectorAll("button").length&&Array.from(grid.querySelectorAll("button")).some(b=>b.dataset.name===c.name))return;const b=document.createElement("button");b.type="button";b.dataset.name=c.name;b.title=c.name;const label=document.createElement("span");label.textContent=c.name;const wordmark=document.createElement("strong");wordmark.className="odpc-tv-wordmark";wordmark.textContent=c.name;wordmark.setAttribute("aria-hidden","true");b.append(wordmark);if(c.logo){const img=document.createElement("img");img.alt="";img.loading="lazy";img.onload=()=>{if(img.naturalWidth>0){wordmark.hidden=true;img.hidden=false}};img.onerror=()=>{img.remove();wordmark.hidden=false};img.hidden=true;img.src=c.logo;b.append(img)}b.append(label);b.onclick=()=>play(c);const idx=channels.indexOf(c);const next=Array.from(grid.children).find(el=>channels.findIndex(x=>x.name===el.dataset.name)>idx);grid.insertBefore(b,next||null)}async function probe(c){return new Promise(resolve=>{const v=document.createElement("video");v.muted=true;v.playsInline=true;v.preload="auto";let h=null,done=false;const finish=ok=>{if(done)return;done=true;clearTimeout(timer);if(h)h.destroy();v.pause();v.removeAttribute("src");v.load();resolve(ok)};const timer=setTimeout(()=>finish(false),9000);v.addEventListener("playing",()=>finish(true),{once:true});v.addEventListener("error",()=>finish(false),{once:true});h=attach(c,v,()=>{},()=>finish(false));v.play().catch(()=>finish(false))})}async function start(){if(!window.Hls&&!video.canPlayType("application/vnd.apple.mpegurl")){status.textContent="HLS-Wiedergabe wird von diesem Browser nicht unterstützt";return}let count=0;for(const c of channels){const ok=await probe(c);if(ok){show(c);count++}status.textContent=count?count+" geprüfte Sender verfügbar":"Prüfe verfügbare HD-Sender …"}if(!count)status.textContent="Aktuell kein Stream erfolgreich geprüft. Bitte Seite später erneut laden."}start()})();</script>';
